# admin module: glinet_api, calls the GL.iNet web API (oui-httpd) on the router itself.
# Registered with mcp_register_admin only; the launcher ships this file only with --admin.
#
# The way in is "ubus call gl-session call {module, func, params}": gl-ngx-session
# passes it to the web API on 127.0.0.1, which needs no session for a local caller, so
# the firmware's own validators and service reloads apply as they do for the web UI.
#
# What may run is decided by the method catalog in server/61-admin-glinet-catalog.sh
# (_ga_catalog; generated by scripts/glinet-methods.sh from the API documentation):
#   q  query    runs
#   a  active   runs; what it changed in /etc/config is reported
#   r  risky    runs only with confirm: true; changes are reported
# A method the catalog does not have runs like "a" when its name starts with get_,
# check_ or load_, and like "r" otherwise.

mcp_register_admin glinet_api <<'EOF'
{"name":"glinet_api","title":"GL.iNet web API (read and change settings)",
"description":"Calls one method of the GL.iNet web API on the router, the same API the GL.iNet web interface uses, so the firmware checks the parameters and reloads the services itself: Wi-Fi, WAN, LAN and DHCP, DNS, firewall and port forwards, VPN clients and servers, Tailscale, ZeroTier, AdGuard Home, modem and SMS, GoodCloud, system. Only on GL.iNet firmware 4.x; prefer it there to uci_change for everything the web interface can set. HOW TO USE: (1) call it with no arguments for the API objects this router has; (2) call it with object (or with search) to read the methods, their parameters and their class; (3) call it with object, method and params. Read the current state with the matching get_ method first, change one thing per call, and read it back afterwards. CLASSES: query methods just run. Active methods run and the result lists what changed in /etc/config. Methods marked CONFIRM (reboot, factory reset, firmware flashing, passwords, access ports, anything that deletes, opens the router to the internet, hands it to a cloud account or can cut the user off) are not run until the call has confirm true: set it only when the user has asked for exactly this action in this conversation, otherwise ask first, saying what will happen. Methods the catalog does not know need confirm too unless their name starts with get_, check_ or load_. The catalog describes firmware 4.8 of one model; other models have more or fewer objects and fields, the router's answer decides. Secrets in answers (Wi-Fi keys, passwords, private keys, tokens) are masked unless the server runs with --no-redact.",
"inputSchema":{"type":"object","properties":{
"object":{"type":"string","description":"API object (module), for example wifi, firewall, wg-server, system. Alone: lists the methods of this object with their parameters. Omit it for the list of objects."},
"method":{"type":"string","description":"Method of the object, for example get_config. With it the call is made; without it nothing is called and the catalog is listed."},
"params":{"type":"object","description":"The method's parameters as a JSON object, exactly the fields the listing names (nested objects and arrays as documented, for example rules[].ip is a field ip in each element of the array rules). Default {}."},
"confirm":{"type":"boolean","description":"true: run a method marked CONFIRM. Only after the user has agreed to exactly this call (method and params). Without it such a method is not called and the result says what to ask. Default false.","default":false},
"search":{"type":"string","description":"Listing only: show the methods whose object, name, summary or parameter names contain this text (case ignored), for example \"port forward\" or \"ssid\". With object: within that object."},
"timeout":{"type":"integer","description":"Seconds to wait for the router's answer, 1 to 600. Default 30. Raise it for slow methods (plugins.update_repository up to 180, ovpn-server certificate work up to 300, scans). After a timeout the router may still be working on the call.","default":30,"minimum":1,"maximum":600}},
"additionalProperties":false},
"annotations":{"title":"GL.iNet web API (read and change settings)","readOnlyHint":false,"destructiveHint":true,"idempotentHint":false,"openWorldHint":true}}
EOF
mcp_own_timeout glinet_api

_GA_RPC=/usr/lib/oui-httpd/rpc

# _ga_ubus_bin: sets _ga_ub to the ubus program: the firmware image's own when it has
# one (an overlay copy cannot stand in for it), else the one in PATH. Fails without ubus.
_ga_ubus_bin() {
	if [ -f "$MCP_ROM/bin/ubus" ] && [ -x "$MCP_ROM/bin/ubus" ]; then
		_ga_ub=$MCP_ROM/bin/ubus
	elif have ubus; then
		_ga_ub=ubus
	else
		return 1
	fi
}

# _ga_present FILE: writes the API objects of this router to FILE, one per line, sorted
# (the names in /usr/lib/oui-httpd/rpc without ".so" or ".lua"). Fails when that
# directory cannot be listed; the listings then show the whole catalog.
_ga_present() {
	: >"$1"
	[ -d "$_GA_RPC" ] || return 1
	# names only; anything that is not a plain object name is left out
	# shellcheck disable=SC2012
	ls "$_GA_RPC" 2>/dev/null | sed 's/\.so$//; s/\.lua$//' |
		awk '/^[A-Za-z0-9_-]+$/ && !($0 in s) { s[$0] = 1; print }' | sort >"$1"
	[ -s "$1" ]
}

# _ga_doc MODE OBJECT METHOD SEARCH KNOWN PRESENT: print from the catalog.
#   MODE overview   the objects, those of this router first
#        methods    the methods of OBJECT (or all, when OBJECT is empty) that match
#                   SEARCH; with OBJECT also their parameters
#        one        OBJECT.METHOD with its parameters
#   KNOWN 1: the file PRESENT lists the objects this router has; 0: unknown
# Exit status 1 when "methods" or "one" found nothing.
_ga_doc() {
	{ sed 's/^/X	/' "$6" 2>/dev/null; _ga_catalog; } | awk -F '\t' \
		-v mode="$1" -v obj="$2" -v meth="$3" -v search="$4" -v known="$5" '
	function tag(c) { return c == "q" ? "[query]" : c == "r" ? "[CONFIRM]" : "[active]" }
	function flush(   show, i, away) {
		if (hm == "") return
		show = 0
		if (mode == "one") show = (ho == obj && hm == meth)
		else if (mode == "methods") show = ((obj == "" || ho == obj) && (search == "" || index(tolower(hay), search) > 0))
		if (show) {
			shown++
			away = ""
			if (known == 1 && !(ho in pres)) away = "  (not on this router)"
			printf "%s.%s  %s  %s%s\n", ho, hm, tag(hc), hs, away
			if (obj != "") {
				if (hc == "r") printf "    confirm needed: %s\n", hw
				else if (hw != "") printf "    note: %s\n", hw
				for (i = 1; i <= np; i++) print pl[i]
			}
		}
		hm = ""; np = 0
	}
	BEGIN { search = tolower(search) }
	$1 == "X" { pres[$2] = 1; po[++npo] = $2; next }
	$1 == "O" { flush(); on[++no] = $2; sum[$2] = $4; next }
	$1 == "M" {
		flush()
		ho = $2; hm = $3; hc = $4; hw = $5; hs = $6; np = 0
		cnt[$2 "/" $4]++
		hay = $2 "." $3 " " $6 " " $5
		next
	}
	$1 == "P" {
		if ($4 == "y") req = "required"; else if ($4 == "n") req = "optional"; else req = "required " $4
		en = ""
		if ($5 != "") en = "; one of " $5
		pl[++np] = "    " $2 " (" $3 ", " req en "): " $6
		hay = hay " " $2
		next
	}
	END {
		flush()
		if (mode == "one") { if (shown) exit 0; exit 1 }
		if (mode == "methods") {
			if (shown) exit 0
			if (search != "" && obj != "") printf "no method of %s matches \"%s\"\n", obj, search
			else if (search != "") printf "no method matches \"%s\"\n", search
			exit 1
		}
		# overview
		n = 0; und = 0; nm = 0; miss = ""
		for (i = 1; i <= no; i++) { o = on[i]; doc[o] = 1; if (known != 1 || (o in pres)) n++ }
		for (i = 1; i <= npo; i++) if (!(po[i] in doc)) und++
		if (known == 1) printf "\n== API objects on this router (%d)\n", n + und
		else printf "\n== API objects in the catalog (%d)\n", n
		for (i = 1; i <= no; i++) {
			o = on[i]
			if (known == 1 && !(o in pres)) { if (nm++) miss = miss ", "; miss = miss o; continue }
			printf "%s  (%d query, %d active, %d confirm)  %s\n", o, cnt[o "/q"], cnt[o "/a"], cnt[o "/r"], sum[o]
		}
		for (i = 1; i <= npo; i++) if (!(po[i] in doc)) printf "%s  (not in the catalog: methods unknown)\n", po[i]
		if (nm) printf "\n== In the catalog, not on this router (%d)\n%s\n", nm, miss
	}'
}

# _ga_mask: filter for the API answer as ubus prints it (one JSON member per line):
# masks the values of members that hold secrets by GL.iNet's names, whatever their JSON
# type, and private keys inside longer strings (a WireGuard or OpenVPN client config).
# redact runs after it for the names the core knows.
_ga_mask() {
	if [ "$MCP_REDACT" != 1 ]; then cat; return; fi
	awk '
	function secret(n) {
		n = tolower(n)
		if (n ~ /(^|_)(pub|public)_?key$/) return 0
		if (n ~ /password|passwd|pwd|passphrase|passcode|secret|credential/) return 1
		if (n ~ /(^|[_-])(key|psk|pass|token|sid)$/ || n ~ /(private|preshared)_?key/) return 1
		if (n ~ /^(sim_?)?(pin|puk)(_?code)?$/) return 1
		return 0
	}
	# a line that holds key material inside a string: the same line with it masked
	function inner(s,   out, a, b) {
		out = ""
		while (match(s, /(PrivateKey|PresharedKey) *= *([A-Za-z0-9+\/]|\\\/)+=*/)) {
			a = substr(s, RSTART, RLENGTH); sub(/=.*/, "= <redacted>", a)
			out = out substr(s, 1, RSTART - 1) a; s = substr(s, RSTART + RLENGTH)
		}
		s = out s; out = ""
		# PEM blocks go with their markers: redact, which runs next, takes a BEGIN
		# line as the start of a multi-line key and would drop the lines after it
		while (match(s, /-----BEGIN [A-Za-z0-9 ]*(PRIVATE KEY|Static key V1)-----/)) {
			out = out substr(s, 1, RSTART - 1) "<redacted private key>"; s = substr(s, RSTART + RLENGTH)
			if (match(s, /-----END [A-Za-z0-9 ]*-----/)) { s = substr(s, RSTART + RLENGTH); continue }
			# no end marker: everything up to the closing quote of the string goes
			if (match(s, /",?[ \t]*$/)) s = substr(s, RSTART); else s = ""
			break
		}
		return out s
	}
	skip {
		# inside the object or array of a masked member: its closing line ends it
		match($0, /^[ \t]*/)
		if (RLENGTH == sind && $0 ~ /^[ \t]*[]}],?[ \t]*$/) {
			skip = 0
			if ($0 ~ /,[ \t]*$/) print spre "\"<redacted>\","; else print spre "\"<redacted>\""
		}
		next
	}
	{
		line = $0
		if (match(line, /^[ \t]*"[^"]*"[ \t]*:[ \t]*/)) {
			pre = substr(line, 1, RLENGTH); val = substr(line, RLENGTH + 1)
			name = pre; sub(/^[ \t]*"/, "", name); sub(/".*/, "", name)
			if (secret(name)) {
				if (val ~ /^[[{][ \t]*$/) { match(line, /^[ \t]*/); sind = RLENGTH; spre = pre; skip = 1; next }
				if (val !~ /^(""|null|true|false|\[ *\]|\{ *\}),?[ \t]*$/) {
					if (val ~ /,[ \t]*$/) print pre "\"<redacted>\","; else print pre "\"<redacted>\""
					next
				}
			}
		}
		if (line ~ /PrivateKey|PresharedKey|-----BEGIN /) line = inner(line)
		print line
	}'
}

# _ga_unknown_class METHOD: the class of a method the catalog does not have
_ga_unknown_class() {
	case $1 in get_* | check_* | load_*) echo a ;; *) echo r ;; esac
}

# _ga_to is set by arg_int (eval), _rt_fired by run_timeout (server/00-core.sh)
# shellcheck disable=SC2154
tool_glinet_api() {
	arg _ga_obj object ''
	arg _ga_meth method ''
	arg _ga_search search ''
	arg_int _ga_to timeout 30 1 600 || return
	_ga_t0=$(date +%s)
	case $_ga_obj in *[!A-Za-z0-9_-]*) tool_error "object must be an API object name (letters, digits, - and _), got '$_ga_obj'"; return ;; esac
	case $_ga_meth in *[!A-Za-z0-9_]*) tool_error "method must be a method name (letters, digits and _), got '$_ga_meth'"; return ;; esac
	[ -z "$(printf '%s' "$_ga_search" | tr -d ' -~')" ] || { tool_error "search must be plain ASCII text"; return; }

	if [ ! -f /etc/glversion ] && [ ! -d "$_GA_RPC" ]; then
		tool_error "this router does not run GL.iNet firmware 4.x (no /etc/glversion, no $_GA_RPC): there is no GL.iNet web API here. Use uci_change and service_control instead."
		return
	fi
	_ga_ver=$(rd /etc/glversion 2>/dev/null | head -n 1 | tr -cd 'A-Za-z0-9._-')
	_ga_type=$(rd /etc/version.type 2>/dev/null | head -n 1 | tr -cd 'A-Za-z0-9._-')
	_ga_known=1
	_ga_present present || _ga_known=0

	# gl-session reachable? (needed for a call, only reported in a listing)
	_ga_sess=0 _ga_why=''
	if ! _ga_ubus_bin; then
		_ga_why="ubus: not available"
	else
		run_timeout 10 "$_ga_ub" list gl-session >session 2>/dev/null
		if grep -q '^gl-session$' session 2>/dev/null; then
			_ga_sess=1
		else
			_ga_why="ubus has no object gl-session (gl-ngx-session not running, or ubusd not reachable)"
		fi
	fi

	# ------------------------------------------------------------ listing
	if [ -z "$_ga_meth" ]; then
		printf 'GL.iNet firmware %s%s\n' "${_ga_ver:-unknown version}" "${_ga_type:+ ($_ga_type)}"
		if [ "$_ga_sess" = 1 ]; then
			echo "gl-session: available, calls can be made"
		else
			echo "gl-session: NOT available, no call can be made now: $_ga_why"
		fi
		[ "$_ga_known" = 1 ] || echo "cannot list $_GA_RPC: which catalog objects this router has is unknown"
		if [ -z "$_ga_obj" ] && [ -z "$_ga_search" ]; then
			echo "Next: object alone lists its methods and parameters; search finds methods by keyword; object + method (+ params) calls."
			echo "[query] runs. [active] runs and reports config changes. [CONFIRM] runs only with confirm: true, after the user agreed to exactly that call."
			_ga_doc overview '' '' '' "$_ga_known" present
			if [ "$_ga_known" = 1 ]; then
				echo
				echo "Objects not in the catalog: their methods are unknown here (read $_GA_RPC/OBJECT and /usr/share/gl-validator.d/OBJECT.lua). Calling one needs confirm unless the method name starts with get_, check_ or load_."
			fi
			return 0
		fi
		if [ -n "$_ga_obj" ]; then
			_ga_osum=$(_ga_catalog | awk -F '\t' -v o="$_ga_obj" '$1 == "O" && $2 == o { print $3 ": " $4; exit }')
			_ga_here=''
			if [ "$_ga_known" = 1 ]; then
				if grep -q -x -e "$_ga_obj" present; then _ga_here=', on this router'; else _ga_here=', NOT on this router'; fi
			fi
			if [ -z "$_ga_osum" ]; then
				if [ "$_ga_known" = 1 ] && grep -q -x -e "$_ga_obj" present; then
					echo
					echo "$_ga_obj is on this router but not in the catalog: its methods are unknown here. Read $_GA_RPC/$_ga_obj (when it is a Lua script) and /usr/share/gl-validator.d/$_ga_obj.lua with read_file to find them. Calling one needs confirm unless the method name starts with get_, check_ or load_."
					return 0
				fi
				tool_error "no API object '$_ga_obj' in the catalog${_ga_here}. Call glinet_api without arguments for the objects."
				return
			fi
			section "$_ga_obj ($_ga_osum)$_ga_here"
		else
			section "Methods matching \"$_ga_search\""
		fi
		_ga_doc methods "$_ga_obj" '' "$_ga_search" "$_ga_known" present || :
		return 0
	fi

	# ------------------------------------------------------------ call
	[ -n "$_ga_obj" ] || { tool_error "method needs object: which API object has $_ga_meth?"; return; }
	[ -z "$_ga_search" ] || { tool_error "search is for listings: leave out method to search, or leave out search to call"; return; }
	_ga_name=$_ga_obj.$_ga_meth

	if [ "$_ga_known" = 1 ] && ! grep -q -x -e "$_ga_obj" present; then
		tool_error "$_ga_name: not called. This router has no API object '$_ga_obj' (nothing of that name in $_GA_RPC). Call glinet_api without arguments for the objects it has."
		return
	fi

	# class, reason and summary from the catalog
	_ga_row=$(_ga_catalog | awk -F '\t' -v o="$_ga_obj" -v m="$_ga_meth" '$1 == "M" && $2 == o && $3 == m { print $4 "\t" $5 "\t" $6; exit }')
	if [ -n "$_ga_row" ]; then
		_ga_class=${_ga_row%%	*}
		_ga_rest=${_ga_row#*	}
		_ga_reason=${_ga_rest%%	*}
		_ga_sum=${_ga_rest#*	}
		_ga_cataloged=1
	else
		_ga_class=$(_ga_unknown_class "$_ga_meth")
		_ga_reason="not in the method catalog (it describes firmware 4.8 of one model): what this method does is unknown"
		_ga_sum='(not documented)'
		_ga_cataloged=0
	fi

	arg _ga_params params '{}'
	case $_ga_params in '{'*) ;; *) _ga_params='{}' ;; esac
	_ga_empty=0
	case $(printf '%s' "$_ga_params" | tr -d ' \t\n') in '{}') _ga_empty=1 ;; esac

	# a risky method runs only with confirm
	if [ "$_ga_class" = r ] && ! arg_bool confirm false; then
		echo "$_ga_name: NOT CALLED, it needs confirmation. Nothing was changed."
		echo "What it does: $_ga_sum"
		echo "Why confirmation: $_ga_reason."
		echo
		echo "What to do: if the user has not asked for exactly this action in this conversation, ask now. Say in plain words what will be done (this method with the params you sent) and what it means for them (see above); for a call that can cut the connection, say that the router may become unreachable and how they would get back in. When the user agrees, send the same call again with \"confirm\": true added. Do not set confirm for a different method or other params than the user agreed to."
		if [ "$_ga_cataloged" = 1 ]; then
			echo
			_ga_doc one "$_ga_obj" "$_ga_meth" '' 0 /dev/null
		fi
		return 1
	fi

	# a changing method that has required parameters, called with none: show them
	# instead of sending an empty change
	if [ "$_ga_class" != q ] && [ "$_ga_empty" = 1 ] && [ "$_ga_cataloged" = 1 ] &&
		_ga_catalog | awk -F '\t' -v o="$_ga_obj" -v m="$_ga_meth" '
			$1 == "M" { on = ($2 == o && $3 == m) }
			$1 == "P" && on && $4 == "y" && $2 !~ /[.<]|\[/ { f = 1 }
			END { if (f) exit 0; exit 1 }'; then
		echo "$_ga_name: NOT CALLED, params is empty but the method has required parameters. Nothing was changed."
		echo
		_ga_doc one "$_ga_obj" "$_ga_meth" '' 0 /dev/null
		return 1
	fi

	if [ "$_ga_sess" != 1 ]; then
		tool_error "$_ga_name: not called. GL.iNet firmware ${_ga_ver:-(unknown version)} is here, but the web API cannot be reached: $_ga_why."
		return
	fi

	_ga_req="{\"module\":\"$_ga_obj\",\"func\":\"$_ga_meth\",\"params\":$_ga_params}"
	if [ "${#_ga_req}" -gt 100000 ]; then
		tool_error "$_ga_name: not called. params is ${#_ga_req} bytes; more than 100000 cannot be passed to ubus."
		return
	fi

	[ "$_ga_cataloged" = 1 ] || echo "note: $_ga_name is not in the method catalog; nothing is known here about its parameters or effects."
	[ "$_ga_class" = q ] || lib_cfg_snapshot cfg
	# the wait is the timeout, less what the config comparison after the call needs to
	# stay inside the call limit (it takes about as long as everything before the call)
	_ga_el=$(($(date +%s) - _ga_t0))
	_ga_lim=${MCP_CALL_TIMEOUT:-120}
	[ $((_ga_to + 5)) -le "$_ga_lim" ] || _ga_lim=$((_ga_to + 5))
	_ga_wait=$((_ga_lim - 2 * _ga_el - 3))
	[ "$_ga_wait" -le "$_ga_to" ] || _ga_wait=$_ga_to
	[ "$_ga_wait" -ge 1 ] || _ga_wait=1
	run_timeout "$_ga_wait" "$_ga_ub" -t "$_ga_wait" call gl-session call "$_ga_req" >answer 2>ubus.err
	_ga_rc=$?
	_ga_fired=$_rt_fired
	_ga_bad=0

	if { [ "$_ga_rc" = 124 ] && [ "$_ga_fired" = 1 ]; } || [ "$_ga_rc" = 7 ]; then
		echo "$_ga_name: NO ANSWER after $_ga_wait s (timeout). The router may still be working on the call or may have finished it: read the state back before trying again, and use a longer timeout for slow methods."
		_ga_bad=1
	elif [ "$_ga_rc" != 0 ]; then
		echo "$_ga_name: the ubus call failed (exit $_ga_rc): $(head -c 300 ubus.err | tr '\n' ' ')"
		case $_ga_rc in 3 | 4) echo "ubus no longer finds gl-session or its method call." ;; esac
		_ga_bad=1
	else
		case $(jsonfilter -i answer -t '@.error' 2>/dev/null) in
		object)
			_ga_code=$(jsonfilter -i answer -e '@.error.code' 2>/dev/null | head -n 1 | tr -cd '0-9-')
			_ga_msg=$(jsonfilter -i answer -e '@.error.message' 2>/dev/null | head -n 1 | tr -d '\000-\037' | cut -c1-300)
			echo "$_ga_name: GL API ERROR ${_ga_code:-?}: ${_ga_msg:-(no message)}"
			_ga_bad=1
			case $_ga_code in
			-32602)
				echo "The firmware's validator rejected params (a wrong name, type or value, or a missing field). Nothing was changed. Compare with the documented parameters and send it again:"
				echo
				_ga_doc one "$_ga_obj" "$_ga_meth" '' 0 /dev/null ||
					echo "($_ga_name is not in the catalog; /usr/share/gl-validator.d/$_ga_obj.lua on the router holds the rules)"
				;;
			-32601) echo "This firmware has no method $_ga_name. Nothing was changed. List the object's methods with object alone." ;;
			-32000) echo "The web API refused the call (access denied)." ;;
			*) [ "$_ga_class" = q ] || echo "The method reported an error; it may have applied part of the change: see the config changes below and read the state back." ;;
			esac
			;;
		'' | null)
			echo "$_ga_name: ok"
			_ga_em=$(jsonfilter -i answer -e '@.result.err_msg' 2>/dev/null | head -n 1 | tr -d '\000-\037' | cut -c1-300)
			[ -z "$_ga_em" ] || echo "but the answer carries err_msg: $_ga_em"
			;;
		*)
			echo "$_ga_name: GL API ERROR: $(jsonfilter -i answer -e '@.error' 2>/dev/null | head -n 1 | tr -d '\000-\037' | cut -c1-300)"
			_ga_bad=1
			;;
		esac
	fi

	if [ "$_ga_class" != q ]; then
		section "Config changes (/etc/config, right after the call; the firmware may still be applying them)"
		lib_cfg_changes cfg
	fi
	if [ -s answer ]; then
		section "Answer"
		_ga_mask <answer | redact
	fi
	return "$_ga_bad"
}
